const role=document.body.dataset.role,base='https://neo-lead-crm-api.umakanthgilla.workers.dev/api/'+role+'/',key='neo_'+role+'_token';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let token=sessionStorage.getItem(key)||'',data=null,tab='overview',generation=0,portalNotifications=[],backStack=[],lastRenderedTab=null,goingBack=false,backRestoreScroll=null,selectedChildId='';
const parentAccountKey=()=>{try{const payload=JSON.parse(atob(token.split('.')[0].replace(/-/g,'+').replace(/_/g,'/')));return payload.account_id||payload.student_id||'unknown'}catch{return 'session'}};
const parentReadKey=()=> 'neo_parent_seen_'+parentAccountKey();
