const seenAlerts=()=>{try{return new Set(JSON.parse(localStorage.getItem(parentReadKey())||'[]'))}catch{return new Set()}};
const unreadAlerts=kind=>(data?.[kind]||[]).filter(x=>x.id&&!seenAlerts().has(kind+':'+x.id)).length;
function markParentRead(kind,id){if(!id)return;const seen=seenAlerts();seen.add(kind+':'+id);try{localStorage.setItem(parentReadKey(),JSON.stringify([...seen].slice(-300)))}catch{}const badge=$('familyAlertBell')?.querySelector('.portal-alert-count');if(badge){const count=unreadAlerts('transport_alerts')+unreadAlerts('announcements')+unreadAlerts('fee_reminders');badge.textContent=String(count);badge.hidden=!count;window.NeoAlertSound?.count('parent:'+parentReadKey(),count);$('familyAlertBell').setAttribute('aria-label',count+' unread school and transport updates')}}
const money=x=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format(x/100),status=s=>{$('familyStatus').textContent=s;const loginStatus=$('familyLoginStatus');if(loginStatus)loginStatus.textContent=s};
function logout(){window.NeoTransportPush?.signOut(token);generation++;token='';data=null;selectedChildId='';backStack=[];lastRenderedTab=null;backRestoreScroll=null;sessionStorage.removeItem(key);$('familyApp').hidden=true;$('familyApp').replaceChildren();$('familyLogout').hidden=true;$('familyLogin').hidden=false}
async function api(path,method='GET',body){const headers={Authorization:'Bearer '+token,'Content-Type':'application/json',...(role==='parent'&&selectedChildId?{'X-Neo-Student':selectedChildId}:{})};const r=await fetch(base+path,{method,headers,...(body?{body:JSON.stringify(body)}:{})});const b=await r.json().catch(()=>({error:'Unreadable server response.'}));if(!r.ok){if(r.status===401&&path!=='login')logout();throw Error(b.error||'Request failed.')}return b}
async function learningApi(path,body){const headers={Authorization:'Bearer '+token,'Content-Type':'application/json',...(role==='parent'&&selectedChildId?{'X-Neo-Student':selectedChildId}:{})};const r=await fetch('https://neo-lead-crm-api.umakanthgilla.workers.dev/api/learning/'+path,{method:body?'POST':'GET',headers,...(body?{body:JSON.stringify(body)}:{})});const b=await r.json();if(!r.ok)throw Error(b.error||'Learning request failed.');return b}
async function portalBlob(path){const headers={Authorization:'Bearer '+token,...(role==='parent'&&selectedChildId?{'X-Neo-Student':selectedChildId}:{})};const r=await fetch(base+path,{headers});if(!r.ok){const b=await r.json().catch(()=>({error:'Photo unavailable.'}));throw Error(b.error||'Photo unavailable.')}return r.blob()}
async function refresh(silent=false){const stamp=++generation;if(!silent)status('Loading your workspace…');try{const next=await api('me');if(role==='parent'&&next.selected_student_id){selectedChildId=next.selected_student_id;sessionStorage.setItem(parentChildKey(),selectedChildId)}const kinds=role==='parent'?['feed','timetable','calendar','period-execution']:['feed','plans','timetable','calendar','period-execution'];const responses=await Promise.allSettled(kinds.map(k=>learningApi(k)));next.learning={errors:{}};responses.forEach((r,i)=>{if(r.status==='fulfilled')next.learning[kinds[i]]=r.value;else next.learning.errors[kinds[i]]=r.reason.message});if(role==='teacher'){try{const hr=await api('hr');portalNotifications=hr.notifications||[]}catch(_){portalNotifications=[]}}else{portalNotifications=[]}if(stamp!==generation)return;if(silent&&$('reportPreview'))return;if(silent&&JSON.stringify(next)===JSON.stringify(data))return;data=next;$('familyLogin').hidden=true;$('familyLogout').hidden=false;$('familyApp').hidden=false;render();if(!silent)status('Updated: '+new Date().toLocaleTimeString('en-IN')+'. Latest saved school updates loaded.')}catch(e){if(stamp===generation||!token)status(e.message)}}
