$('familyLoginForm').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;status('Signing in…');try{const b=await api('login','POST',Object.fromEntries(new FormData(e.target)));token=b.token;sessionStorage.setItem(key,token);selectedChildId=role==='parent'?(sessionStorage.getItem(parentChildKey())||''):'';e.target.reset();await refresh()}catch(error){status(error.message)}finally{e.submitter.disabled=false}};

