 const oldContent=$('familyContent');if(lastRenderedTab!==null&&lastRenderedTab!==tab){if(!goingBack){backStack.push({tab:lastRenderedTab,scroll:oldContent?.scrollTop||0});if(backStack.length>30)backStack.shift()}const position=backRestoreScroll;requestAnimationFrame(()=>{if($('familyContent'))$('familyContent').scrollTop=position??0})}lastRenderedTab=tab;goingBack=false;backRestoreScroll=null;
