 const departments=role==='parent'?[['Learning & classroom',['calendar','timetable','activities','attendance','homework','ptm_reports']],['School & support',['fees','announcements','tickets','supplies','transport']],['Documents & account',['downloads','password']]]:[['Academics & teaching',['calendar','timetable','curriculum','performance','student_care','activities','attendance','homework','tasks']],['School communication',['announcements','tickets']],['My HR',['employee_hub']],['Documents & account',['downloads','password']]];
 const departmentNav=departments.map(([title,keys],index)=>`<details class="family-department" name="family-departments" ${keys.includes(tab)?'open':''}><summary>${familyBadge(familyDepartmentIcon[role][title],index%5)}<span class="family-department-label">${esc(title)}</span><span aria-hidden="true" class="family-department-chevron"></span></summary><div class="family-department-items">${keys.map(k=>`<button type="button" data-tab="${k}" aria-pressed="${k===tab}">${familyNavIcon(k,index%5)}${esc(tabs[k])}</button>`).join('')}</div></details>`).join('');
 const transportAlertCount=role==='parent'?unreadAlerts('transport_alerts'):0;const familyAlertCount=role==='parent'?transportAlertCount+unreadAlerts('announcements')+unreadAlerts('fee_reminders'):portalNotifications.filter(x=>x.status!=='Read').length;window.NeoAlertSound?.count(role+':'+(role==='parent'?parentReadKey():data.name),familyAlertCount);
 $('familyApp').innerHTML=`${familyIconSprite}<div class="portal-hero"><div><span class="eyebrow">NEO · ${role.toUpperCase()} PORTAL</span><h2>${esc(role==='parent'?data.child.name:data.name)}</h2><p>${esc(data.school.name)} · ${esc(data.school.city)}</p><div class="family-hero-actions"><span class="portal-pill">${role==='parent'?esc((data.child.admission_no?data.child.admission_no+' · ':'')+data.child.program+' · '+data.child.academic_year):data.classrooms.length+' assigned classrooms'}</span>${role==='parent'&&Array.isArray(data.children)&&data.children.length>1?`<label class="family-child-switch"><span>Child</span><select id="familyChildSwitch" aria-label="Select child">${data.children.map(child=>`<option value="${esc(child.id)}" ${child.id===(data.selected_student_id||data.child.id)?'selected':''}>${esc(child.name+' · '+child.program)}</option>`).join('')}</select></label>`:''}<button type="button" id="familyBackTop" class="portal-hero-back" ${backStack.length?'':'hidden'} aria-label="Go back to previous screen">← Back</button></div></div><button type="button" id="familyHeroRefresh" class="portal-hero-refresh" title="Refresh latest updates" aria-label="Refresh latest updates">↻</button><button type="button" id="familyAlertBell" class="portal-alert-bell" aria-label="${role==='parent'?familyAlertCount+' school and transport updates':familyAlertCount+' unread notifications'}"><svg class="portal-bell-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2a2 2 0 0 0-2 2v.35C7.08 5.2 5 7.9 5 11v4.1l-1.7 2.55A1 1 0 0 0 4.13 19h15.74a1 1 0 0 0 .83-1.55L19 15.1V11c0-3.1-2.08-5.8-5-6.65V4a2 2 0 0 0-2-2Zm-2.35 19a2.5 2.5 0 0 0 4.7 0h-4.7Z"/></svg><span class="portal-alert-count" ${familyAlertCount?'':'hidden'}>${familyAlertCount}</span></button><img src="/neo%20owl.jpeg" alt="Neo owl" width="85" height="105"></div><nav class="family-tabs" aria-label="${role} workspace"><button type="button" id="familyMobileMenu" class="portal-mobile-menu" aria-expanded="false" aria-controls="familyNavScroll">☰ Sections</button><div class="family-nav-scroll" id="familyNavScroll"><button type="button" data-tab="overview" aria-pressed="${tab==='overview'}" class="family-overview-tab">${familyNavIcon("overview")}${esc(tabs.overview)}</button>${departmentNav}<button id="familyDownload" class="secondary">${familyNavIcon("downloads",4)}<span class="family-download-label">Preview download</span></button></div><button type="button" id="familySignOut" class="family-signout">${familyBadge("logout",0)}<span>Sign out</span></button></nav><div id="familyContent"></div>`;
 $('familyMobileMenu').onclick=()=>{const nav=$('familyApp').querySelector('.family-tabs');const open=nav.classList.toggle('mobile-menu-open');$('familyMobileMenu').setAttribute('aria-expanded',String(open))};
 const childSwitch=$('familyChildSwitch');if(childSwitch)childSwitch.onchange=async()=>{selectedChildId=childSwitch.value;sessionStorage.setItem(parentChildKey(),selectedChildId);backStack=[];lastRenderedTab=null;status('Switching child…');await refresh()};
 $('familyApp').querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$('familyAlertBell').onclick=()=>{tab=role==='teacher'?'hr_desk':transportAlertCount?'transport':unreadAlerts('fee_reminders')?'fees':'announcements';render()};const goBack=()=>{const previous=backStack.pop();if(!previous)return;tab=previous.tab;backRestoreScroll=previous.scroll;goingBack=true;render()};$('familyBackTop').onclick=goBack;$('familySignOut').onclick=()=>{logout();status('Signed out.')};$('familyHeroRefresh').onclick=()=>refresh();
 const reportNames={overview:'Learning updates',performance:'Child performance',activities:'Learning updates',attendance:'Attendance',homework:'Homework',fees:'Fee statement',announcements:'School notices',tickets:'Complaint history',supplies:'Books and uniforms',transport:'Transport',timetable:'Timetable',curriculum:'Curriculum',tasks:'Tasks'};
 const name=reportNames[tab];$('familyDownload').hidden=!name;$('familyDownload').querySelector('.family-download-label').textContent=name?'Preview '+name+' download':'Download';

